class Category extends DataClass
    implements Insertable<Category>, CategorySnapshot {
  /// 分类编号只在所属账号内唯一，默认模板可在各账号保存独立内容。
  final String id;
  final String name;

  /// 分类类型，固定为 expense。
  final String kind;

  /// 层级: 1=一级, 2=二级(契约字段 level)。
  final int level;
  final int sortOrder;
  final String? icon;

  /// 父分类 UUID(契约字段 parent_id)。
  /// 父编号只在同一账号解析，分页尚未到达的父节点保留为待确认关系。
  final String? parentId;

  /// 账号数据域：null = 本机域；非 null = 云账号 user_id（每账号一份）。
  final String? scopeAccountId;

  /// 云端精确版本凭证；离线种子没有凭证，不能冒充已读取云端基线。
  final String? serverVersionToken;

  /// 当前账号的分类已由云端确认，登记状态与用于并发校验的版本凭证分别维护。
  final bool cloudRegistered;

  /// 已观测的云端状态独立于本机草稿，历史确认回执不能覆盖后来收到的云版本。
  final String? observedCloudState;
  final DateTime updatedAt;

  /// 本地 tombstone。
  final DateTime? deletedAt;
  const Category({
    required this.id,
    required this.name,
    required this.kind,
    required this.level,
    required this.sortOrder,
    this.icon,
    this.parentId,
    this.scopeAccountId,
    this.serverVersionToken,
    required this.cloudRegistered,
    this.observedCloudState,
    required this.updatedAt,
    this.deletedAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['name'] = Variable<String>(name);
    map['kind'] = Variable<String>(kind);
    map['level'] = Variable<int>(level);
    map['sort_order'] = Variable<int>(sortOrder);
    if (!nullToAbsent || icon != null) {
      map['icon'] = Variable<String>(icon);
    }
    if (!nullToAbsent || parentId != null) {
      map['parent_id'] = Variable<String>(parentId);
    }
    if (!nullToAbsent || scopeAccountId != null) {
      map['scope_account_id'] = Variable<String>(
        $CategoriesTable.$converterscopeAccountId.toSql(scopeAccountId),
      );
    }
    if (!nullToAbsent || serverVersionToken != null) {
      map['server_version_token'] = Variable<String>(serverVersionToken);
    }
    map['cloud_registered'] = Variable<bool>(cloudRegistered);
    if (!nullToAbsent || observedCloudState != null) {
      map['observed_cloud_state'] = Variable<String>(observedCloudState);
    }
    {
      map['updated_at'] = Variable<int>(
        $CategoriesTable.$converterupdatedAt.toSql(updatedAt),
      );
    }
    if (!nullToAbsent || deletedAt != null) {
      map['deleted_at'] = Variable<int>(
        $CategoriesTable.$converterdeletedAtn.toSql(deletedAt),
      );
    }
    return map;
  }

  CategoriesCompanion toCompanion(bool nullToAbsent) {
    return CategoriesCompanion(
      id: Value(id),
      name: Value(name),
      kind: Value(kind),
      level: Value(level),
      sortOrder: Value(sortOrder),
      icon: icon == null && nullToAbsent ? const Value.absent() : Value(icon),
      parentId: parentId == null && nullToAbsent
