      );
    }
    if (serverVersionToken.present) {
      map['server_version_token'] = Variable<String>(serverVersionToken.value);
    }
    if (cloudRegistered.present) {
      map['cloud_registered'] = Variable<bool>(cloudRegistered.value);
    }
    if (observedCloudState.present) {
      map['observed_cloud_state'] = Variable<String>(observedCloudState.value);
    }
    if (updatedAt.present) {
      map['updated_at'] = Variable<int>(
        $CategoriesTable.$converterupdatedAt.toSql(updatedAt.value),
      );
    }
    if (deletedAt.present) {
      map['deleted_at'] = Variable<int>(
        $CategoriesTable.$converterdeletedAtn.toSql(deletedAt.value),
      );
    }
    if (rowid.present) {
      map['rowid'] = Variable<int>(rowid.value);
    }
    return map;
  }

  @override
  String toString() {
    return (StringBuffer('CategoriesCompanion(')
          ..write('id: $id, ')
          ..write('name: $name, ')
          ..write('kind: $kind, ')
          ..write('level: $level, ')
          ..write('sortOrder: $sortOrder, ')
          ..write('icon: $icon, ')
          ..write('parentId: $parentId, ')
          ..write('scopeAccountId: $scopeAccountId, ')
          ..write('serverVersionToken: $serverVersionToken, ')
          ..write('cloudRegistered: $cloudRegistered, ')
          ..write('observedCloudState: $observedCloudState, ')
          ..write('updatedAt: $updatedAt, ')
          ..write('deletedAt: $deletedAt, ')
          ..write('rowid: $rowid')
          ..write(')'))
        .toString();
  }
}

