class RecurringTransaction extends DataClass
    implements Insertable<RecurringTransaction>, RecurringTransactionSnapshot {
  /// UUID v4 主键(仅经 sync push 创建,客户端生成)。
  final String id;
  final String ledgerId;
  final String txType;

  /// 模板金额:规范化 Decimal 字符串。
  final String amount;

  /// 模板原记账币种。
  final String currencyCode;
  final String? categoryId;
  final String? note;

  /// 重复规则: daily/weekly/monthly/yearly。
  final String frequency;

  /// 周期规则统一使用确定性发生协议。
  final int protocolVersion;

  /// 持久化 IANA 时区，不随设备旅行或时区切换改变发生日期。
  final String timeZone;
  final int interval;
  final int? dayOfMonth;
  final int? dayOfWeek;
  final int? monthOfYear;
  final DateTime startDate;
  final DateTime? endDate;
  final DateTime? lastGeneratedDate;
  final bool enabled;
  final DateTime createdAt;

  /// 规则的 LWW 版本保留服务端毫秒精度，作为下一次人工编辑的时钟基线。
  final DateTime updatedAt;

  /// 本地 tombstone。
  final DateTime? deletedAt;
  const RecurringTransaction({
    required this.id,
    required this.ledgerId,
    required this.txType,
    required this.amount,
    required this.currencyCode,
    this.categoryId,
    this.note,
    required this.frequency,
    required this.protocolVersion,
    required this.timeZone,
    required this.interval,
    this.dayOfMonth,
    this.dayOfWeek,
    this.monthOfYear,
    required this.startDate,
    this.endDate,
    this.lastGeneratedDate,
    required this.enabled,
    required this.createdAt,
    required this.updatedAt,
    this.deletedAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['ledger_id'] = Variable<String>(ledgerId);
    map['tx_type'] = Variable<String>(txType);
    map['amount'] = Variable<String>(amount);
    map['currency_code'] = Variable<String>(currencyCode);
    if (!nullToAbsent || categoryId != null) {
      map['category_id'] = Variable<String>(categoryId);
    }
    if (!nullToAbsent || note != null) {
      map['note'] = Variable<String>(note);
    }
    map['frequency'] = Variable<String>(frequency);
    map['protocol_version'] = Variable<int>(protocolVersion);
    map['time_zone'] = Variable<String>(timeZone);
    map['interval'] = Variable<int>(interval);
    if (!nullToAbsent || dayOfMonth != null) {
      map['day_of_month'] = Variable<int>(dayOfMonth);
    }
    if (!nullToAbsent || dayOfWeek != null) {
      map['day_of_week'] = Variable<int>(dayOfWeek);
    }
    if (!nullToAbsent || monthOfYear != null) {
      map['month_of_year'] = Variable<int>(monthOfYear);
    }
    map['start_date'] = Variable<DateTime>(startDate);
    if (!nullToAbsent || endDate != null) {
      map['end_date'] = Variable<DateTime>(endDate);
    }
    if (!nullToAbsent || lastGeneratedDate != null) {
      map['last_generated_date'] = Variable<DateTime>(lastGeneratedDate);
    }
    map['enabled'] = Variable<bool>(enabled);
    map['created_at'] = Variable<DateTime>(createdAt);
    {
      map['updated_at'] = Variable<int>(
        $RecurringTransactionsTable.$converterupdatedAt.toSql(updatedAt),
      );
    }
    if (!nullToAbsent || deletedAt != null) {
      map['deleted_at'] = Variable<int>(
        $RecurringTransactionsTable.$converterdeletedAtn.toSql(deletedAt),
      );
    }
    return map;
  }

  RecurringTransactionsCompanion toCompanion(bool nullToAbsent) {
    return RecurringTransactionsCompanion(
      id: Value(id),
      ledgerId: Value(ledgerId),
      txType: Value(txType),
      amount: Value(amount),
      currencyCode: Value(currencyCode),
      categoryId: categoryId == null && nullToAbsent
          ? const Value.absent()
          : Value(categoryId),
      note: note == null && nullToAbsent ? const Value.absent() : Value(note),
      frequency: Value(frequency),
      protocolVersion: Value(protocolVersion),
      timeZone: Value(timeZone),
      interval: Value(interval),
      dayOfMonth: dayOfMonth == null && nullToAbsent
          ? const Value.absent()
          : Value(dayOfMonth),
      dayOfWeek: dayOfWeek == null && nullToAbsent
          ? const Value.absent()
          : Value(dayOfWeek),
      monthOfYear: monthOfYear == null && nullToAbsent
          ? const Value.absent()
          : Value(monthOfYear),
      startDate: Value(startDate),
      endDate: endDate == null && nullToAbsent
          ? const Value.absent()
          : Value(endDate),
      lastGeneratedDate: lastGeneratedDate == null && nullToAbsent
          ? const Value.absent()
          : Value(lastGeneratedDate),
      enabled: Value(enabled),
      createdAt: Value(createdAt),
      updatedAt: Value(updatedAt),
      deletedAt: deletedAt == null && nullToAbsent
          ? const Value.absent()
          : Value(deletedAt),
    );
  }

