class SyncChange extends DataClass implements Insertable<SyncChange> {
  /// 本地自增队列序号(纯本地)。
  final int id;

  /// 契约 entity_type: ledger/transaction/category/recurring_transaction/
  /// exchange_rate_override/virtual_user。
  final String entityType;

  /// 契约 entity_id: UUID。
  final String entityId;

  /// 契约 ledger_id: user-global 实体为 null。
  final String? ledgerId;

  /// 日子父本边界，与财务 ledger_id 互斥。
  final String? dayBookId;
  final String? memoBookId;
  final String? fitnessSpaceId;

  /// 首次发送前持久化完整请求；未知结果重试只能重放该快照。
  final String? frozenRequest;

  /// 归属账号（数据域）：未登录时的本地 mutation 为 null，不参与任何账号的推送；
  /// 非 null 时只有该账号的 SyncService 能读取/推送。
  final String? accountId;

  /// 契约 action: upsert/delete。
  final String action;

  /// 完整实体 JSON(契约 payload)。
  final String payload;

  /// 未冻结请求的唯一编辑时间，按 UTC 毫秒保存，正文不承载队列时钟。
  final DateTime updatedAt;

  /// 非 null 表示已推送(服务端确认后清除或标记)。
  final DateTime? pushedAt;

  /// 服务端确定拒绝后的脱敏原因；非空时保留本地变更，等待修正后重新登记。
  final String? rejectionReason;

  /// 服务端稳定拒绝码；同步恢复使用错误类别，展示文案只用于向用户解释。
  final String? rejectionCode;

  /// 幂等键(UUID,契约 mutation_id):离线创建时生成,推送重试复用同一值,
  /// 服务端按 (device_id, mutation_id) 去重,防止网络重试重复落库。
  final String mutationId;

  /// 乐观并发基线：该 mutation 基于的服务端 revision。
  /// 同实体链式递增(前序 base+1),服务端据此做 CAS 冲突检测。
  final int? baseRevision;
  const SyncChange({
    required this.id,
    required this.entityType,
    required this.entityId,
    this.ledgerId,
    this.dayBookId,
    this.memoBookId,
    this.fitnessSpaceId,
    this.frozenRequest,
    this.accountId,
    required this.action,
    required this.payload,
    required this.updatedAt,
    this.pushedAt,
    this.rejectionReason,
    this.rejectionCode,
    required this.mutationId,
    this.baseRevision,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['entity_type'] = Variable<String>(entityType);
    map['entity_id'] = Variable<String>(entityId);
    if (!nullToAbsent || ledgerId != null) {
      map['ledger_id'] = Variable<String>(ledgerId);
    }
    if (!nullToAbsent || dayBookId != null) {
      map['day_book_id'] = Variable<String>(dayBookId);
    }
    if (!nullToAbsent || memoBookId != null) {
      map['memo_book_id'] = Variable<String>(memoBookId);
    }
    if (!nullToAbsent || fitnessSpaceId != null) {
      map['fitness_space_id'] = Variable<String>(fitnessSpaceId);
    }
    if (!nullToAbsent || frozenRequest != null) {
      map['frozen_request'] = Variable<String>(frozenRequest);
    }
    if (!nullToAbsent || accountId != null) {
      map['account_id'] = Variable<String>(accountId);
    }
    map['action'] = Variable<String>(action);
    map['payload'] = Variable<String>(payload);
    {
      map['updated_at'] = Variable<int>(
        $SyncChangesTable.$converterupdatedAt.toSql(updatedAt),
      );
    }
    if (!nullToAbsent || pushedAt != null) {
      map['pushed_at'] = Variable<DateTime>(pushedAt);
    }
    if (!nullToAbsent || rejectionReason != null) {
      map['rejection_reason'] = Variable<String>(rejectionReason);
    }
    if (!nullToAbsent || rejectionCode != null) {
      map['rejection_code'] = Variable<String>(rejectionCode);
    }
    map['mutation_id'] = Variable<String>(mutationId);
    if (!nullToAbsent || baseRevision != null) {
      map['base_revision'] = Variable<int>(baseRevision);
    }
