class SyncConflict extends DataClass implements Insertable<SyncConflict> {
  /// 冲突所属账号；本机私有本的未确认分支没有账号归属，此时为 NULL。
  final String? accountId;
  final String? dayBookId;
  final String? memoBookId;
  final String? fitnessSpaceId;

  /// 冲突记录主键；分类沿用服务端候选 ID，其他领域使用本地 UUID。
  final String id;

  /// 冲突所属账本；账号级分类冲突为空。
  final String? ledgerId;

  /// 冲突实体类型，包含账号级分类及各业务域实体。
  final String entityType;

  /// 冲突实体 id。
  final String entityId;

  /// 本地版本(实体 JSON):取冲突实体的最新 pending mutation payload。
  final String localPayload;

  /// 云端版本(实体 JSON):push 冲突取服务端 current_entity;
  /// delete 冲突以 {"deleted":true,"revision":N} 表达云端已删除。
  final String remotePayload;

  /// 冲突基线:本地 pending mutation 的 base_revision。
  final int baseRevision;

  /// 冲突时云端 revision。
  final int remoteRevision;

  /// 产生冲突的本地 mutation id(解决后用于清理 pending 队列)。
  final String localMutationId;

  /// 分类确认的冻结请求；回执未知时只重放原始决策与幂等身份。
  final String? resolutionRequest;

  /// 冲突状态: OPEN / RESOLVED_LOCAL / RESOLVED_REMOTE。
  final String status;
  final DateTime createdAt;
  final DateTime? resolvedAt;
  const SyncConflict({
    this.accountId,
    this.dayBookId,
    this.memoBookId,
    this.fitnessSpaceId,
    required this.id,
    this.ledgerId,
    required this.entityType,
    required this.entityId,
    required this.localPayload,
    required this.remotePayload,
    required this.baseRevision,
    required this.remoteRevision,
    required this.localMutationId,
    this.resolutionRequest,
    required this.status,
    required this.createdAt,
    this.resolvedAt,
  });
